#!/usr/bin/env python3
"""Re-derive pi's package resolution when pi itself is not installed (CI).

Source of truth, read at pi 0.85.0: dist/core/pi-manifest.js (readPiManifest)
and dist/core/package-manager.js (collectFilesFromManifestEntries,
collectSkillEntries, applyPatterns). This arm cannot notice pi changing those
rules; the REAL arm in test-pi-plugin.sh is what covers that, and the driver
prints which arm ran. Usage: check-rules.py <repo-root> <expected-skill-count>
"""

import fnmatch
import json
import sys
from pathlib import Path

OVERRIDE_PREFIXES = ("!", "+", "-")


def collect(directory: Path, start: Path) -> list[Path]:
    """collectSkillEntries(dir, mode="pi").

    A directory holding SKILL.md IS a skill and stops the walk. Otherwise take
    the .md children of the entry directory itself and recurse into subdirs.
    """
    if (directory / "SKILL.md").is_file():
        return [directory / "SKILL.md"]
    found: list[Path] = []
    for child in sorted(directory.iterdir()):
        if child.name.startswith(".") or child.name == "node_modules":
            continue
        if child.is_file() and child.suffix == ".md" and directory == start:
            found.append(child)
        elif child.is_dir():
            found.extend(collect(child, start))
    return found


def main(root: Path, expected: int) -> None:
    # Resolve both sides. On macOS /tmp is a symlink to /private/tmp, so a
    # resolved child under an unresolved root is not "in the subpath of" it.
    root = root.resolve()
    entries = json.loads((root / "package.json").read_text())["pi"]["skills"]
    sources = [e for e in entries if not e.startswith(OVERRIDE_PREFIXES)]
    # applyPatterns: "!" is an exclude, "-" a force-exclude. Both remove here;
    # they differ only against a "+" force-include, which this repo does not use.
    patterns = [e[1:] for e in entries if e.startswith(("!", "-"))]

    files: list[Path] = []
    for entry in sources:
        start = (root / entry).resolve()
        if start.is_file():
            files.append(start)
        elif start.is_dir():
            files.extend(collect(start, start))

    kept: list[str] = []
    for path in files:
        rel = path.relative_to(root).as_posix()
        if any(rel == pat or fnmatch.fnmatch(rel, pat) for pat in patterns):
            continue
        kept.append(rel)

    skill_files = [p for p in kept if p.endswith("SKILL.md")]
    if len(skill_files) != expected:
        raise SystemExit(f"FAIL: pi rules resolve {len(skill_files)} SKILL.md, tree has {expected}")
    strays = sorted(set(kept) - set(skill_files))
    if strays:
        raise SystemExit(
            "FAIL: pi would also collect non-skill markdown, which shows up in `pi list` "
            f"as a resource that parses to nothing: {strays}"
        )


if __name__ == "__main__":
    main(Path(sys.argv[1]), int(sys.argv[2]))
